def subtract(a, b):
    def normalize(intervals):
        ivs = [(s, e) for s, e in intervals if s < e]
        ivs.sort()
        merged = []
        for s, e in ivs:
            if merged and s <= merged[-1][1]:
                if e > merged[-1][1]:
                    merged[-1] = (merged[-1][0], e)
            else:
                merged.append((s, e))
        return merged

    A = normalize(a)
    B = normalize(b)

    result = []
    bi = 0
    for s, e in A:
        cur = s
        # advance bi to first interval in B that could overlap [cur, e)
        while bi < len(B) and B[bi][1] <= cur:
            bi += 1
        j = bi
        while j < len(B) and B[j][0] < e:
            bs, be = B[j]
            if bs > cur:
                result.append([cur, bs])
            if be > cur:
                cur = be
            j += 1
            if cur >= e:
                break
        if cur < e:
            result.append([cur, e])

    # merge touching intervals in result
    result.sort()
    merged = []
    for s, e in result:
        if merged and merged[-1][1] == s:
            merged[-1][1] = e
        else:
            merged.append([s, e])
    return merged

